  const ALL_KEYS = CARDS.flatMap(c => c.keys.map(k => k[0]));
  const REMOVED = ['L@EURUSD', 'L2@XAUUSD', 'Q@US30', 'R@EURUSD', 'A@EURUSD', 'RM@EURUSD', 'RM@XAUUSD'];   // 2026-11-07: off for good, not shown
